#include <stdio.h>
#include <unistd.h>
#include <fcntl.h>
int main() {
  int fd = open("server.conf", O_RDWR);
  struct flock fl = { .l_type = F_WRLCK, .l_whence = SEEK_SET, .l_start = 0, .l_len = 0 };
  int res = fcntl(fd, F_SETLK, &fl);
