gcc -Wall -Wextra -xc - -o /tmp/sigmask_bin << "CEOF"
#include <stdio.h>
#include <signal.h>
int main() {
  sigset_t set, pend;
  sigemptyset(&set);
  sigaddset(&set, SIGUSR1);
  sigprocmask(SIG_BLOCK, &set, NULL);
  raise(SIGUSR1);
  sigpending(&pend);
  printf("SIGUSR1_PENDING: %s\n", sigismember(&pend, SIGUSR1) ? "YES" : "NO");
  return 0;
}
CEOF
/tmp/sigmask_bin

