#include <stdio.h>
#include <stddef.h>
#define container_of(ptr, type, member) ((type *)((char *)(ptr) - offsetof(type, member)))
struct list_head { struct list_head *next, *prev; };
struct process_node { int pid; struct list_head list; };
int main() {
  struct process_node p1 = { .pid = 101 };
  struct list_head *lh = &p1.list;
  struct process_node *recovered = container_of(lh, struct process_node, list);
  printf("KERNEL_CONTAINER_OF_PID: %d\n", recovered->pid);
  return 0;
}
